	if (tkw->hvcc) gf_odf_hevc_cfg_del(tkw->hvcc);
	if (tkw->lvcc) gf_odf_hevc_cfg_del(tkw->lvcc);
	if (tkw->inband_hdr) gf_free(tkw->inband_hdr);
	gf_free(tkw);
}

